export const PRECACHED_BRIDGES: Record<
  VoicePersona,
  Record<VoiceBridgeType, PrecachedBridge[]>
> = {
  akosua: MULTILINGUAL_BRIDGES.akosua.en,
  kwame: MULTILINGUAL_BRIDGES.kwame.en,
  esi: MULTILINGUAL_BRIDGES.esi.en,
};

let lastBridgeIndex = -1;
export const getPrecachedBridge = (
  type: VoiceBridgeType,
  persona: VoicePersona = 'akosua',
  language: VoiceLanguage = 'en'
): PrecachedBridge | null => {
  const langKey = language === 'twi' || language === 'pidgin' ? language : 'en';
  const personaPool = MULTILINGUAL_BRIDGES[persona] || MULTILINGUAL_BRIDGES.akosua;
  const langPool = personaPool[langKey] || personaPool.en;
  const pool = langPool[type] || langPool.balance;
  if (!pool || pool.length === 0) return null;
  let nextIdx = Math.floor(Math.random() * pool.length);
  if (pool.length > 1 && nextIdx === lastBridgeIndex) {
    nextIdx = (nextIdx + 1) % pool.length;
  }
  lastBridgeIndex = nextIdx;
  return pool[nextIdx];
};

// Backward compatibility exports
export const PRECACHED_BALANCE_BRIDGES = PRECACHED_BRIDGES.akosua.balance;
export const PRECACHED_EXPENSE_BRIDGES = PRECACHED_BRIDGES.akosua.expense;
export const PRECACHED_BUDGET_BRIDGES = PRECACHED_BRIDGES.akosua.budget;
export const PRECACHED_REPORT_BRIDGES = PRECACHED_BRIDGES.akosua.report;
